('lib/content/gpx_scolarite/dps_dpg/generalite_pages/libertés_publiques/individuelles/droit_vie_privee_page.dart','f00064','1.1 — La vidéoprotection',64,'TextSpan','Après information du maire de la commune concernée et autorisation des autorités publiques compétentes, ','Après information du maire de la commune concernée et autorisation des autorités publiques compétentes, ','{}'::jsonb,true),
('lib/content/gpx_scolarite/dps_dpg/generalite_pages/libertés_publiques/individuelles/droit_vie_privee_page.dart','f00065','1.1 — La vidéoprotection',65,'TextSpan','des commerçants peuvent mettre en œuvre sur la voie publique un système de vidéoprotection pour assurer la protection des abords immédiats de leurs bâtiments et installations ','des commerçants peuvent mettre en œuvre sur la voie publique un système de vidéoprotection pour assurer la protection des abords immédiats de leurs bâtiments et installations ','{}'::jsonb,true),
