('lib/content/gpx_scolarite/dps_dpg/generalite_pages/libertés_publiques/individuelles/droit_vie_privee_page.dart','f00080','1.1 — La vidéoprotection',80,'string','ainsi que les mesures nécessaires pour assurer le respect des dispositions des articles L. 251-1 à L. 255-1 du Code de la sécurité intérieure (article L. 252-2). ','ainsi que les mesures nécessaires pour assurer le respect des dispositions des articles L. 251-1 à L. 255-1 du Code de la sécurité intérieure (article L. 252-2). ','{}'::jsonb,true),
