('lib/content/gpx_scolarite/dps_dpg/generalite_pages/libertés_publiques/individuelles/droit_vie_privee_page.dart','f00086','1.1 — La vidéoprotection',86,'TextSpan','Ils doivent être conformes à des normes techniques fixées par arrêté du ministre de l’Intérieur (article L. 252-4 du Code de la sécurité intérieure). ','Ils doivent être conformes à des normes techniques fixées par arrêté du ministre de l’Intérieur (article L. 252-4 du Code de la sécurité intérieure). ','{}'::jsonb,true),
