('lib/content/gpx_scolarite/dps_dpg/generalite_pages/libertés_publiques/individuelles/droit_vie_privee_page.dart','f00089','1.1 — La vidéoprotection',89,'TextSpan','Lorsque l’urgence et l’exposition particulière à un risque d’actes de terrorisme le justifient (article L. 223-4 du Code de la sécurité intérieure), ','Lorsque l’urgence et l’exposition particulière à un risque d’actes de terrorisme le justifient (article L. 223-4 du Code de la sécurité intérieure), ','{}'::jsonb,true),
